#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, m, c;
    if (!(cin >> n >> m >> c)) return 0;

    // nextSong[s] = musica amada pelo amigo cliente ha mais tempo que detesta s (0 se ninguem detesta s)
    vector<int> nextSong(m + 1, 0);

    for (int i = 0; i < n; i++) {
        int a, d;
        cin >> a >> d;
        if (nextSong[d] == 0) nextSong[d] = a; // mantem o amigo mais antigo (primeiro na ordem de leitura)
    }

    // O proximo passo depende apenas da musica atual:
 // se alguem detesta a musica atual, o mais antigo detestador troca pela musica que ama.
    // Logo, basta seguir a cadeia a partir de C, detectando ciclo (revisita) -> -1.
    vector<char> visited(m + 1, 0);
    int cur = c;
    long long steps = 0;

    while (nextSong[cur] != 0) {
        if (visited[cur]) {
            cout << -1 << "\n";
            return 0;
        }
        visited[cur] = 1;
        cur = nextSong[cur];
        steps++;
    }

    cout << steps << "\n";
    return 0;
}
